const input = $input.first().json;
const data = input.body || input;

const target     = data['Target URL'] || data.target;
const vulnType   = data['Vulnerability Type'] || 'sqli';
const depth      = parseInt(data.Depth) || 2;
const authToken  = data['Auth Token'] || '';

if (!target || !target.startsWith('http')) {
  throw new Error('Invalid target: ' + target);
}

const WORDLISTS = {
  sqli:    '/seeds/SecLists/Fuzzing/Databases/SQLi/Generic-SQLi.txt',
  xss:     '/seeds/SecLists/Fuzzing/XSS/XSS-Jhaddix.txt',
  lfi:     '/seeds/SecLists/Fuzzing/LFI/LFI-Jhaddix.txt',
  cmd:     '/seeds/SecLists/Fuzzing/command-injection-commix.txt',
  ssti:    '/seeds/SecLists/Fuzzing/template-engines-special-vars.txt',
  special: '/seeds/SecLists/Fuzzing/special-chars.txt',
  universal: '/seeds/payloads.txt',
};

const wordlist = WORDLISTS[vulnType];
if (!wordlist) throw new Error('Unknown vuln_type: ' + vulnType);

const ts  = new Date().toISOString().replace(/[:.]/g, '-');
const slug = target.replace(/https?:\/\//, '').replace(/[^a-z0-9]/gi, '_');
const experiment = `n8n_${vulnType}_${slug}_${ts}`;

return [{
  json: {
    target, vulnType, depth, authToken, wordlist, ts, slug, experiment,
    runId: experiment,
    katanaOut: `/results/katana_${experiment}.txt`,
    ffufOut:   `/results/ffuf_${experiment}.json`,
    wfuzzOut:  `/results/wfuzz_${experiment}.txt`,
    feroxbusterOut: `/results/feroxbuster_${experiment}.json`,
    reportOut: `/results/report_${experiment}.json`,
    baselineUrl: `${target}${target.includes('?') ? '&' : '?'}id=1`,
    baselineOut: `/results/baseline_${experiment}.json`,
    startTime: Date.now(),
    baseUrl: (target.match(/^(https?:\/\/[^\/]+)/) || [])[1] || target,
    openApiUrl: `${(target.match(/^(https?:\/\/[^\/]+)/) || [])[1] || target}/openapi.json`,
    schemathesisOut: `/results/schemathesis_${experiment}.xml`,
    arjunOut: `/results/arjun_${experiment}.json`,
  }
}];

const cfg = $('Validate Config').first().json;
const resp = $input.first().json;
const fs = require('fs');

const rawBody = resp.data ?? resp.body ?? '';

let bodyStr = '';
if (typeof rawBody === 'string') {
  bodyStr = rawBody;
} else if (rawBody && typeof rawBody === 'object') {
  bodyStr = JSON.stringify(rawBody);
}

const status = resp.statusCode || resp.status || 0;

const clHeader = resp.headers?.['content-length'];
const length = clHeader ? parseInt(clHeader) : bodyStr.length;

const baseline = {
  url: cfg.baselineUrl,
  status: status,
  length: length,
  timestamp: new Date().toISOString(),
};

try {
  fs.writeFileSync(cfg.baselineOut, JSON.stringify(baseline, null, 2));
  console.log('Baseline saved:', baseline);
} catch (e) {
  console.error('baseline write failed:', e.message);
}

return [{
  json: {
    ...cfg,
    baseline: baseline,
    baselineLength: baseline.length,
    baselineStatus: baseline.status,
  }
}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 2000));

let xhrEndpoints = [];
let formParams = [];

const file = `/results/puppeteer_${cfg.runId}.json`;

if (fs.existsSync(file)) {
  try {
    const data = JSON.parse(fs.readFileSync(file, 'utf8'));

    xhrEndpoints = (data.xhr || [])
      .map(r => r.url.split('?')[0])
      .filter(u => u.startsWith('http'))
      .filter((v, i, a) => a.indexOf(v) === i);

    formParams = (data.forms || [])
      .map(f => f.name)
      .filter(n => n && !n.includes('['))
      .filter((v, i, a) => a.indexOf(v) === i);
  } catch (e) {
    console.error('Puppeteer parse error:', e.message);
  }
}

return [{
  json: {
    ...cfg,
    puppeteerXhr: xhrEndpoints,
    puppeteerForms: formParams,
  }
}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

const raw = $input.first().json.stdout || '';

const paths = raw
  .split('\n')
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('Running against'))
  .filter(line => line.startsWith('/') || line.startsWith('http'))
  .filter(line => {
    if (/^https?:\/\/(www\.)?(owasp|youtube|fonts|google|w3|testnets|ipinfo|api\.ipinfo)/i.test(line)) return false;
    if (/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map)$/i.test(line)) return false;
    return true;
  })
  .filter((v, i, a) => a.indexOf(v) === i);

const outFile = `/results/linkfinder_${cfg.runId}.txt`;
fs.writeFileSync(outFile, paths.join('\n'));

return [{
  json: {
    ...cfg,
    linkfinderPaths: paths,
    linkfinderCount: paths.length,
    linkfinderOut: outFile,
  }
}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 1500));

let content = '';
try {
  content = fs.readFileSync(cfg.katanaOut, 'utf8');
} catch (e) {
  content = cfg.target + '\n';
}

const endpoints = content
  .split('\n')
  .map(l => l.trim())
  .filter(l => l && l.includes('http'))
  .filter(l => !/\.(png|jpg|jpeg|gif|css|js|mjs|jsx|ts|tsx|woff2?|ico|svg|map|ttf|eot|webp|avif|mp4|webm)$/i.test(l))
  .filter(l => {
    if (l === cfg.target) return true;
    if (l.includes('?')) return true;
    if (/\/(rest|api|admin|user|search|login|products?|sqli|xss|ssti|rce|ptrav|xxe|redirect)/i.test(l)) return true;
    return false;
  })
  .filter((v, i, a) => a.indexOf(v) === i);

if (!endpoints.includes(cfg.target)) {
  endpoints.unshift(cfg.target);
}

return [{
  json: {
    ...cfg,
    endpoints,
    endpointCount: endpoints.length,
  }
}];

const cfg = $('Validate Config').first().json;
const resp = $input.first().json;

const paths = [];

try {
  const body = resp.data ?? resp.body;
  const spec = typeof body === 'string' ? JSON.parse(body) : body;

  if (spec && spec.paths) {
    for (const path of Object.keys(spec.paths)) {
      const cleanPath = path.replace(/\{[^}]+\}/g, 'FUZZ');
      paths.push(`${cfg.baseUrl}${cleanPath}`);
    }
  }
  console.log(`OpenAPI endpoints: ${paths.length}`);
} catch (e) {
  console.error('OpenAPI parse error:', e.message);
}

return [{
  json: {
    ...cfg,
    openApiEndpoints: paths,
    openApiCount: paths.length,
  }
}];

const cfg = $('Validate Config').first().json;
const items = $input.all();

let katanaEndpoints = [];
let linkfinderPaths = [];
let openApiEndpoints = [];
let puppeteerXhr = [];

for (const item of items) {
  const d = item.json;
  if (Array.isArray(d.endpoints) && d.endpoints.length > 0) katanaEndpoints = d.endpoints;
  if (Array.isArray(d.linkfinderPaths)) linkfinderPaths = d.linkfinderPaths;
  if (Array.isArray(d.openApiEndpoints)) openApiEndpoints = d.openApiEndpoints;
  if (Array.isArray(d.puppeteerXhr)) puppeteerXhr = d.puppeteerXhr;
}

let allEndpoints = [
  ...katanaEndpoints,
  ...linkfinderPaths.filter(p => p.startsWith('/')).map(p => `${cfg.baseUrl}${p}`),
  ...openApiEndpoints,
  ...puppeteerXhr,
];

allEndpoints = allEndpoints
  .filter(ep => !/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map)$/i.test(ep))
  .filter((v, i, a) => a.indexOf(v) === i);

if (allEndpoints.length === 0) allEndpoints.push(cfg.target);

console.log(`Merged: katana=${katanaEndpoints.length}, lf=${linkfinderPaths.length}, openapi=${openApiEndpoints.length}, puppeteer=${puppeteerXhr.length}, total=${allEndpoints.length}`);

return [{
  json: {
    ...cfg,
    endpoints: allEndpoints,
    endpointCount: allEndpoints.length,
  }
}];

const cfg = $input.first().json;

// Берём эндпоинты из Merge Endpoints
const endpoints = (cfg.endpoints || [])
  .filter(ep => !/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map)$/i.test(ep))
  .filter((v, i, a) => a.indexOf(v) === i);

if (endpoints.length === 0) {
  endpoints.push(cfg.target);
}

const DEFAULT_PARAMS = ['id', 'q', 'search', 'query', 'file', 'url', 'name'];

const allParams = {};
for (const ep of endpoints) {
  allParams[ep] = DEFAULT_PARAMS;
}

console.log(`Expand: ${endpoints.length} endpoints, ${DEFAULT_PARAMS.length} params each`);

return [{
  json: {
    ...cfg,
    allParams,
    endpointCount: endpoints.length,
  }
}];

const cfg = $input.first().json;
const allParams = cfg.allParams || {};
const puppeteerParams = cfg.puppeteerForms || [];

for (const [endpoint, params] of Object.entries(allParams)) {
  allParams[endpoint] = [...new Set([...params, ...puppeteerParams])];
}

// СТРОГИЕ паттерны — только реально релевантные эндпоинты
const VULN_PATTERNS = {
  sqli:      /^(.*\/)?(sqli(\/(login|search))?|search|login|api\/users)\/?$/i,
  xss:       /^(.*\/)?(xss(\/(reflected|stored|dom))?|search|contact)\/?$/i,
  cmd:       /^(.*\/)?(rce(\/(ping|eval))?|ping)\/?$/i,
  ptrav:     /^(.*\/)?(ptrav(\/(read|download))?|page)\/?$/i,
  ssti:      /^(.*\/)?(ssti|template)\/?$/i,
  lfi:       /^(.*\/)?(ptrav|page|file|read)\/?$/i,
  redirect:  /^(.*\/)?(redir(ect)?(\/(go|login|redirect))?|open_redirect)\/?$/i,
  xxe:       /^(.*\/)?(xxe(\/parse)?|upload_file)\/?$/i,
  special:   /./,
  universal: /./,
};

const VULN_PARAMS = {
  sqli:      ['id', 'search', 'query'],
  xss:       ['query', 'q', 'input'],
  cmd:       ['host', 'ip', 'cmd'],
  ptrav:     ['file', 'path', 'filename'],
  ssti:      ['template', 'name', 'input'],
  lfi:       ['file', 'page', 'include'],
  redirect:  ['url', 'redirect_to', 'next'],
  xxe:       ['xml', 'data'],
  special:   ['id', 'q', 'search'],
  universal: ['id', 'q', 'search'],
};

const pattern     = VULN_PATTERNS[cfg.vulnType] || /./;
const paramsToUse = VULN_PARAMS[cfg.vulnType]   || ['id'];

const jobs = [];
let i = 0;

for (const [endpoint, _] of Object.entries(allParams)) {
  if (!pattern.test(endpoint)) continue;

  for (const param of paramsToUse) {
    jobs.push({
      endpoint, param,
      target: cfg.target,
      wordlist: cfg.wordlist,
      vulnType: cfg.vulnType,
      authToken: cfg.authToken,
      runId: cfg.runId,
      experiment: cfg.experiment,
      slug: cfg.slug,
      ts: cfg.ts,
      ffufOut:  `/results/ffuf_${cfg.experiment}_${i}.json`,
      wfuzzOut: `/results/wfuzz_${cfg.experiment}_${i}.txt`,
    });
    i++;
    if (i >= 30) break;   // ← ЖЁСТКИЙ ЛИМИТ 30 ЗАДАЧ
  }
  if (i >= 30) break;
}

console.log(`Build jobs: ${jobs.length} tasks (endpoints: ${new Set(jobs.map(j => j.endpoint)).size}, vuln: ${cfg.vulnType})`);

return jobs.map(j => ({ json: j }));

const cfg = $('Validate Config').first().json;
const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 2000));

const jobs = $('Build jobs').all().map(item => item.json);
const normalized = [];

if (!fs.existsSync('/results')) {
  return [{ json: { ...cfg, normalized, totalResults: 0 } }];
}

const files = fs.readdirSync('/results').filter(f =>
  f.startsWith(`ffuf_${cfg.experiment}`) && f.endsWith('.json')
);

for (const file of files) {
  try {
    const full = path.join('/results', file);
    const data = JSON.parse(fs.readFileSync(full, 'utf8'));
    const results = data.results || [];

    const m = file.match(/_(\d+)\.json$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = idx >= 0 && idx < jobs.length ? jobs[idx] : null;

    const endpoint = job ? job.endpoint : cfg.target;
    const param    = job ? job.param    : `param_${idx}`;

    for (const r of results) {
      normalized.push({
        tool: 'ffuf',
        file: file,
        param: param,
        endpoint: endpoint,
        payload: (r.input && r.input.FUZZ) || '',
        status: r.status,
        length: r.length,
        time_ms: Math.round((r.duration || 0) / 1_000_000),
        contentType: r['content-type'] || '',
      });
    }
  } catch (e) {
    console.error('Parse ffuf error:', file, e.message);
  }
}

console.log(`Parsed ffuf: ${normalized.length} results from ${files.length} files`);

return [{ json: { ...cfg, normalized, totalResults: normalized.length } }];

const cfg = $('Validate Config').first().json;
const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 2000));

const jobs = $('Build jobs').all().map(item => item.json);
const normalized = [];

if (!fs.existsSync('/results')) {
  return [{ json: { ...cfg, normalized, totalResults: 0 } }];
}

const files = fs.readdirSync('/results').filter(f =>
  f.startsWith(`wfuzz_${cfg.experiment}`) && f.endsWith('.txt')
);

for (const file of files) {
  try {
    const full = path.join('/results', file);
    const text = fs.readFileSync(full, 'utf8');
    const lines = text.split('\n');

    const m = file.match(/_(\d+)\.txt$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = idx >= 0 && idx < jobs.length ? jobs[idx] : null;

    const endpoint = job ? job.endpoint : cfg.target;
    const param    = job ? job.param    : `param_${idx}`;

    for (const line of lines) {
      const match = line.match(/^\s*\d+:\s+C=(\d+)\s+(\d+)\s+L\s+(\d+)\s+W\s+(\d+)\s+Ch\s+"(.*)"/);
      if (!match) continue;

    normalized.push({
      tool: 'wfuzz',
      file: file,
      param: param,
      endpoint: endpoint,
      payload: (match[5] || '').trim(),
      status:  parseInt(match[1]),
      length:  parseInt(match[4]),   // ← chars (129), как у ffuf
      words:   parseInt(match[3]),
      chars:   parseInt(match[4]),
      time_ms: 0,
    });
    }
  } catch (e) {
    console.error('Parse wfuzz error:', file, e.message);
  }
}

console.log(`Parsed wfuzz: ${normalized.length} results from ${files.length} files`);

return [{ json: { ...cfg, normalized, totalResults: normalized.length } }];

const cfg = $('Validate Config').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 2000));

let normalized = [];
let stats = { total: 0, failures: 0, errors: 0, skipped: 0 };

const file = cfg.schemathesisOut;

if (fs.existsSync(file)) {
  try {
    const xml = fs.readFileSync(file, 'utf8');

    // Счётчики из <testsuites> (порядок: errors, failures, skipped, tests)
    const tsMatch = xml.match(/<testsuites[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*skipped="(\d+)"[^>]*tests="(\d+)"/);
    if (tsMatch) {
      stats.errors   = parseInt(tsMatch[1]);
      stats.failures = parseInt(tsMatch[2]);
      stats.skipped  = parseInt(tsMatch[3]);
      stats.total    = parseInt(tsMatch[4]);
    }

    // Отдельные testcase — только те, у которых есть <failure> или <error>
    const re = /<testcase\s+name="([^"]*)"\s+time="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
    let m;
    while ((m = re.exec(xml)) !== null) {
      const fullName = m[1];
      const time = parseFloat(m[2]) || 0;
      const body = m[3];

      const isFail  = body.includes('<failure');
      const isError = body.includes('<error');
      if (!isFail && !isError) continue;

      // Разбиваем "POST /redirect/login" на method и path
      const parts = fullName.split(' ');
      const method = parts[0];
      const path = parts.slice(1).join(' ') || fullName;

      // Извлекаем текст из <failure>...</failure>
      const msgMatch = body.match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
      let message = '';
      if (msgMatch) {
        message = msgMatch[1]
          .replace(/1\. Test Case ID:[^\n]*\n/g, '')
          .replace(/Reproduce with:[\s\S]*$/m, '')
          .replace(/\s+/g, ' ')
          .trim()
          .slice(0, 500);
      }

      normalized.push({
        tool: 'schemathesis',
        method: method,
        endpoint: path,
        payload: fullName,
        status: 0,
        length: 0,
        time_ms: Math.round(time * 1000),
        message: message,
        isFailure: isFail,
        isError: isError,
      });
    }

    console.log('Schemathesis parsed:', normalized.length, 'findings, stats:', stats);
  } catch (e) {
    console.error('Schemathesis parse error:', e.message);
  }
}

return [{
  json: {
    ...cfg,
    normalized,
    totalResults: normalized.length,
    schemathesisStats: stats,
  }
}];

const cfg = $('Validate Config').first().json;
const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 3000));

const normalized = [];
let stats = { total: 0, failures: 0, errors: 0, skipped: 0 };

// Ищем ВСЕ папки cats_report_*
const allDirs = fs.readdirSync('/results')
  .filter(f => f.startsWith('cats_report_'))
  .map(f => ({
    name: f,
    mtime: fs.statSync(path.join('/results', f)).mtime.getTime(),
  }))
  .sort((a, b) => b.mtime - a.mtime);  // свежие сверху

console.log('CATS dirs found:', allDirs.length);

if (allDirs.length > 0) {
  const reportDir = path.join('/results', allDirs[0].name);
  console.log('Using CATS dir:', reportDir);

  const files = fs.readdirSync(reportDir).filter(f => f.endsWith('.xml'));

  for (const file of files) {
    try {
      const xml = fs.readFileSync(path.join(reportDir, file), 'utf8');

      // Счётчики из <testsuites>
      const m = xml.match(/<testsuites[^>]*skipped="(\d+)"[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*tests="(\d+)"/);
      if (m) {
        stats.skipped = parseInt(m[1]);
        stats.errors = parseInt(m[2]);
        stats.failures = parseInt(m[3]);
        stats.total = parseInt(m[4]);
        console.log('CATS stats:', stats);
      }

      // Находим findings (те, у которых есть <failure> или <error>)
      const re = /<testcase\s+name="([^"]*)"\s+classname="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
      let tc;
      while ((tc = re.exec(xml)) !== null) {
        const body = tc[3];
        const isFail = body.includes('<failure');
        const isError = body.includes('<error');
        if (!isFail && !isError) continue;

        const msgMatch = body.match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
        normalized.push({
          tool: 'cats',
          endpoint: tc[2],
          payload: tc[1],
          status: 0,
          isFailure: isFail,
          isError: isError,
          message: msgMatch ? msgMatch[1].replace(/\s+/g, ' ').trim().slice(0, 200) : '',
        });

        if (normalized.length >= 50) break;
      }
    } catch (e) {
      console.error('CATS parse error:', e.message);
    }
  }
}

console.log(`CATS parsed: ${normalized.length} findings`);

return [{
  json: {
    ...cfg,
    normalized,
    totalResults: normalized.length,
    catsStats: stats,
    catsFindings: normalized.slice(0, 30),
  }
}];

// === БЕЗОПАСНОЕ ЧТЕНИЕ ВСЕХ ПАРСЕРОВ ===
// Если какой-то парсер не выполнился — берём пустую заглушку
const emptyFFUF = {
  normalized: [],
  runId: '', target: '', vulnType: '', wordlist: '', reportOut: ''
};

let ffufData  = emptyFFUF;
let wfuzzData = { normalized: [] };
let schemaData = { normalized: [], schemathesisStats: { failures: 0, errors: 0, skipped: 0 } };
let catsData = { normalized: [], catsStats: { total: 0, failures: 0, errors: 0, skipped: 0 } };

try { ffufData   = $('Parse ffuf').first().json;        } catch (e) { console.warn('Parse ffuf missing'); }
try { wfuzzData  = $('Parse wfuzz').first().json;       } catch (e) { console.warn('Parse wfuzz missing'); }
try { schemaData = $('Parse Schemathesis').first().json; } catch (e) { console.warn('Parse Schemathesis missing'); }
try { catsData   = $('Parse CATS').first().json;        } catch (e) { console.warn('Parse CATS missing'); }

// runId/target берём из Validate Config — Analyze не зависит от ffuf
const cfg = $('Validate Config').first().json;

// === BASELINE ===
let realBaseline = {};
try { realBaseline = $('Save Baseline').first().json.baseline || {}; } catch (e) {}
const baseline = realBaseline.length || 0;
const baselineStatus = realBaseline.status || 200;

console.log('Baseline:', baseline, 'status:', baselineStatus);
console.log('ffuf results:', (ffufData.normalized || []).length);
console.log('wfuzz results:', (wfuzzData.normalized || []).length);

// === СКЛЕЙКА РЕЗУЛЬТАТОВ ===
const allResults = [
  ...(ffufData.normalized  || []),
  ...(wfuzzData.normalized || []),
];

// === ФИЛЬТР АНОМАЛИЙ ===
function isAnomaly(r) {
  if (r.status >= 500) return true;
  if (r.status === 403 || r.status === 401) return true;
  if (r.status === 301 || r.status === 302) return true;
  if (r.status >= 400 && r.status < 500) return true;
  if (r.status === 200 && baseline > 0) {
    const diff = Math.abs(r.length - baseline);
    if (diff > baseline * 0.3) return true;
  }
  if (r.time_ms > 2000) return true;
  return false;
}

const anomalies = [];
const statusBreakdown = {};
const endpointsSet = new Set();
const paramsSet = new Set();

for (const r of allResults) {
  statusBreakdown[r.status] = (statusBreakdown[r.status] || 0) + 1;
  endpointsSet.add(r.endpoint);
  paramsSet.add(r.param);
  if (isAnomaly(r)) anomalies.push(r);
}

const grouped = {};
for (const a of anomalies) {
  const key = `${a.endpoint}?${a.param}`;
  if (!grouped[key]) grouped[key] = [];
  grouped[key].push(a);
}

// === ИТОГ ===
const analysis = {
  runId: cfg.runId,
  target: cfg.target,
  vulnType: cfg.vulnType,
  wordlist: cfg.wordlist,
  reportOut: cfg.reportOut,
  timestamp: new Date().toISOString(),

  baseline, baselineStatus,
  baselineUrl: realBaseline.url || '',
  baselineTimestamp: realBaseline.timestamp || '',

  totalRequests: allResults.length,
  totalAnomalies: anomalies.length,
  anomaliesByStatus: anomalies.reduce((acc, a) => {
    acc[a.status] = (acc[a.status] || 0) + 1;
    return acc;
  }, {}),

  endpointsTested: endpointsSet.size,
  paramsTested: paramsSet.size,
  statusBreakdown,

  tools: {
    ffuf:  { total: (ffufData.normalized  || []).length, anomalies: anomalies.filter(a => a.tool === 'ffuf').length },
    wfuzz: { total: (wfuzzData.normalized || []).length, anomalies: anomalies.filter(a => a.tool === 'wfuzz').length },
    schemathesis: {
      total:    (schemaData.normalized || []).length,
      failures: schemaData.schemathesisStats?.failures || 0,
      errors:   schemaData.schemathesisStats?.errors   || 0,
      skipped:  schemaData.schemathesisStats?.skipped  || 0,
    },
    cats: {
      total:    catsData.catsStats?.total || 0,
      failures: catsData.catsStats?.failures || 0,
      errors:   catsData.catsStats?.errors || 0,
      skipped:  catsData.catsStats?.skipped || 0,
    },
  },

  topAnomalies: anomalies.slice(0, 40),
  groupedByEndpoint: grouped,
  schemathesisFindings: (schemaData.normalized || []).slice(0, 30),
  catsFindings: (catsData.normalized || []).slice(0, 30),
};

